solution.solution.rs:
use std::cell::RefCell;
use std::rc::{Rc, Weak};

struct Node {
    name: String,
    parent: RefCell<Weak<Node>>,
    children: RefCell<Vec<Rc<Node>>>,
}

fn node(name: &str) -> Rc<Node> {
    Rc::new(Node { name: name.to_string(), parent: RefCell::new(Weak::new()), children: RefCell::new(Vec::new()) })
}

fn add_child(parent: &Rc<Node>, child: &Rc<Node>) {
    *child.parent.borrow_mut() = Rc::downgrade(parent);
    parent.children.borrow_mut().push(Rc::clone(child));
}

fn path(n: &Rc<Node>) -> String {
    match n.parent.borrow().upgrade() {
        Some(p) => format!("{}/{}", path(&p), n.name),
        None => n.name.clone(),
    }
}

fn depth(n: &Rc<Node>) -> usize {
    match n.parent.borrow().upgrade() {
        Some(p) => 1 + depth(&p),
        None => 0,
    }
}

fn count(n: &Rc<Node>) -> usize {
    1 + n.children.borrow().iter().map(count).sum::<usize>()
}

fn find(n: &Rc<Node>, name: &str) -> Option<Rc<Node>> {
    if n.name == name {
        return Some(Rc::clone(n));
    }
    n.children.borrow().iter().find_map(|c| find(c, name))
}

fn detach(child: &Rc<Node>) {
    if let Some(parent) = child.parent.borrow().upgrade() {
        parent.children.borrow_mut().retain(|c| !Rc::ptr_eq(c, child));
    }
    *child.parent.borrow_mut() = Weak::new();
}

unitTests:
let build = || {
    let root = node("root");
    let docs = node("docs");
    let notes = node("notes.txt");
    let pics = node("pics");
    add_child(&root, &docs);
    add_child(&docs, &notes);
    add_child(&root, &pics);
    add_child(&pics, &node("cat.png"));
    root
};

test("paths and depths", || {
    let root = build();
    let notes = find(&root, "notes.txt").unwrap();
    check_eq(path(&notes), "root/docs/notes.txt");
    check_eq(depth(&notes), 2);
    check_eq(depth(&root), 0);
    check_eq(path(&root), "root");
});

test("counting and finding", || {
    let root = build();
    check_eq(count(&root), 5);
    check_eq(count(&find(&root, "pics").unwrap()), 2);
    check(find(&root, "missing").is_none());
    check_eq(find(&root, "cat.png").map(|n| path(&n)), Some("root/pics/cat.png".to_string()));
});

test("detaching", || {
    let root = build();
    let docs = find(&root, "docs").unwrap();
    detach(&docs);
    check_eq(count(&root), 3);
    check_eq(path(&docs), "docs");
    check_eq(path(&find(&docs, "notes.txt").unwrap()), "docs/notes.txt");
});

test("weak parents do not keep nodes alive", || {
    let root = build();
    let notes = find(&root, "notes.txt").unwrap();
    let docs = find(&root, "docs").unwrap();
    check_eq(Rc::strong_count(&docs), 2);
    drop(docs);
    drop(root);
    check_eq(depth(&notes), 0);
    check_eq(path(&notes), "notes.txt");
});

